   from FIN_PRODUCT m
INNER JOIN FIN_PRODUCT_TYPE FPT
   ON m.FINPROD_ID = FPT.FINPROD_ID and FPT.TYPE_8 IN (''F03'', ''F04'', ''F09'')
INNER JOIN FIN_PRODUCT_ADD FPA
